UPDATE account_preferences SET dashboard_preferences_json = json_object('workspaceId', (SELECT organization_id FROM memberships WHERE memberships.user_id = account_preferences.user_id AND status = 'active' LIMIT 1), 'dashboard', json(CASE WHEN json_valid(dashboard_preferences_json) THEN dashboard_preferences_json ELSE '{}' END)) WHERE json_extract(CASE WHEN json_valid(dashboard_preferences_json) THEN dashboard_preferences_json ELSE '{}' END, '$.workspaceId') IS NULL;
